22	const FIRST_INSURANCE_SURCHARGE = 0.1;
23	
24	const roundUpInFavourOfMHPCO = (amount: number): number => Math.ceil(Number(amount.toFixed(6)));
25	
26	const quotePremium = (step: QuoteStep): number => {
27	  const policyBasePremium = step.items.reduce(
28	    (sum, item) => sum + BASE_PREMIUM_BY_TYPE[item.type],
29	    0,
30	  );
